import {
	Component,
	Element,
	Fragment,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";

import noDataImg from "./nodata.svg";

/**
 * @since 0.0.10
 * @status stable
 *
 * @slot - The button's label.
 * @slot prefix - Used to prepend an icon or similar element to the button.
 * @slot suffix - Used to append an icon or similar element to the button.
 *
 * @part base - The component's base wrapper.

 */

@Component({
	tag: "hbr-empty",
	styleUrl: "empty.scss",
	shadow: true,
})
export class HbrEmpty {
	@Element() host: HTMLHbrEmptyElement;

	@Prop() description = "No data available...";

	@Prop() imgSrc = noDataImg;

	@State() showSlot = false;

	handleSlotChange = () => {
		this.showSlot = true;
	};

	render() {
		return (
			<Host>
				{!this.showSlot ? (
					<Fragment>
						<img src={this.imgSrc} alt="" />
						<div id="hbr-empty-description">
							<h2>{this.description}</h2>
						</div>
					</Fragment>
				) : null}
				<slot onSlotchange={this.handleSlotChange} />
			</Host>
		);
	}
}
